// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title InvoiceNFT
 * @dev ERC-721 token representing tokenized invoices for TILV platform
 * Each NFT represents a real-world invoice that can be used as collateral for liquidity
 */
contract InvoiceNFT is ERC721, ERC721URIStorage, AccessControl {
    using Counters for Counters.Counter;

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");

    Counters.Counter private _tokenIdCounter;

    enum InvoiceStatus {
        PENDING,        // Invoice uploaded, awaiting validation
        VALIDATED,      // AI validation complete, awaiting funding
        FUNDED,         // Borrower received advance payment
        PAID,           // Buyer paid the invoice
        DEFAULTED,      // Invoice payment overdue
        CANCELLED       // Invoice cancelled
    }

    struct Invoice {
        address borrower;           // SME/merchant who owns the invoice
        address buyer;              // Company that owes payment
        uint256 amount;             // Invoice amount in wei (USDT/USDC)
        uint256 dueDate;            // Payment due date timestamp
        uint256 advanceRate;        // Percentage paid upfront (e.g., 80% = 8000)
        uint256 riskScore;          // Risk score from AI (0-100)
        InvoiceStatus status;       // Current invoice status
        uint256 fundedAmount;       // Amount actually funded
        uint256 createdAt;          // Creation timestamp
        bytes32 validationHash;     // Hash of validation data from AI
        string metadataURI;         // IPFS URI for invoice PDF and metadata
    }

    // Mapping from token ID to invoice data
    mapping(uint256 => Invoice) public invoices;

    // Events
    event InvoiceMinted(
        uint256 indexed tokenId,
        address indexed borrower,
        uint256 amount,
        uint256 riskScore
    );
    
    event InvoiceValidated(uint256 indexed tokenId, uint256 riskScore);
    event InvoiceFunded(uint256 indexed tokenId, uint256 fundedAmount);
    event InvoicePaid(uint256 indexed tokenId, uint256 paidAmount);
    event InvoiceDefaulted(uint256 indexed tokenId);
    event InvoiceCancelled(uint256 indexed tokenId);
    event InvoiceStatusChanged(uint256 indexed tokenId, InvoiceStatus newStatus);

    constructor() ERC721("TILV Invoice", "TINV") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(VALIDATOR_ROLE, msg.sender);
    }

    /**
     * @dev Mint a new invoice NFT
     * @param borrower Address of the invoice owner (SME/merchant)
     * @param buyer Address of the company that owes payment
     * @param amount Invoice amount
     * @param dueDate Payment due date
     * @param metadataURI IPFS URI for invoice document
     * @return tokenId The ID of the newly minted NFT
     */
    function mintInvoice(
        address borrower,
        address buyer,
        uint256 amount,
        uint256 dueDate,
        string memory metadataURI
    ) external onlyRole(MINTER_ROLE) returns (uint256) {
        require(borrower != address(0), "Invalid borrower address");
        require(buyer != address(0), "Invalid buyer address");
        require(amount > 0, "Amount must be greater than 0");
        require(dueDate > block.timestamp, "Due date must be in the future");

        uint256 tokenId = _tokenIdCounter.current();
        _tokenIdCounter.increment();

        _safeMint(borrower, tokenId);
        _setTokenURI(tokenId, metadataURI);

        invoices[tokenId] = Invoice({
            borrower: borrower,
            buyer: buyer,
            amount: amount,
            dueDate: dueDate,
            advanceRate: 0,
            riskScore: 0,
            status: InvoiceStatus.PENDING,
            fundedAmount: 0,
            createdAt: block.timestamp,
            validationHash: bytes32(0),
            metadataURI: metadataURI
        });

        emit InvoiceMinted(tokenId, borrower, amount, 0);
        return tokenId;
    }

    /**
     * @dev Validate an invoice with risk scoring from AI engine
     * @param tokenId The invoice NFT ID
     * @param riskScore Risk score from AI (0-100)
     * @param advanceRate Percentage to advance to borrower
     * @param validationHash Hash of validation data
     */
    function validateInvoice(
        uint256 tokenId,
        uint256 riskScore,
        uint256 advanceRate,
        bytes32 validationHash
    ) external onlyRole(VALIDATOR_ROLE) {
        require(_exists(tokenId), "Invoice does not exist");
        require(invoices[tokenId].status == InvoiceStatus.PENDING, "Invoice already validated");
        require(riskScore <= 100, "Risk score must be <= 100");
        require(advanceRate <= 10000, "Advance rate must be <= 10000 (100%)");

        invoices[tokenId].riskScore = riskScore;
        invoices[tokenId].advanceRate = advanceRate;
        invoices[tokenId].validationHash = validationHash;
        invoices[tokenId].status = InvoiceStatus.VALIDATED;

        emit InvoiceValidated(tokenId, riskScore);
        emit InvoiceStatusChanged(tokenId, InvoiceStatus.VALIDATED);
    }

    /**
     * @dev Mark invoice as funded
     * @param tokenId The invoice NFT ID
     * @param fundedAmount Amount provided to borrower
     */
    function markAsFunded(uint256 tokenId, uint256 fundedAmount) 
        external 
        onlyRole(MINTER_ROLE) 
    {
        require(_exists(tokenId), "Invoice does not exist");
        require(invoices[tokenId].status == InvoiceStatus.VALIDATED, "Invoice not validated");
        
        invoices[tokenId].fundedAmount = fundedAmount;
        invoices[tokenId].status = InvoiceStatus.FUNDED;

        emit InvoiceFunded(tokenId, fundedAmount);
        emit InvoiceStatusChanged(tokenId, InvoiceStatus.FUNDED);
    }

    /**
     * @dev Mark invoice as paid by buyer
     * @param tokenId The invoice NFT ID
     * @param paidAmount Amount paid by buyer
     */
    function markAsPaid(uint256 tokenId, uint256 paidAmount) 
        external 
        onlyRole(VALIDATOR_ROLE) 
    {
        require(_exists(tokenId), "Invoice does not exist");
        require(invoices[tokenId].status == InvoiceStatus.FUNDED, "Invoice not in funded status");
        
        invoices[tokenId].status = InvoiceStatus.PAID;

        emit InvoicePaid(tokenId, paidAmount);
        emit InvoiceStatusChanged(tokenId, InvoiceStatus.PAID);
    }

    /**
     * @dev Mark invoice as defaulted (payment overdue)
     * @param tokenId The invoice NFT ID
     */
    function markAsDefaulted(uint256 tokenId) external onlyRole(VALIDATOR_ROLE) {
        require(_exists(tokenId), "Invoice does not exist");
        require(block.timestamp > invoices[tokenId].dueDate, "Not yet overdue");
        require(invoices[tokenId].status == InvoiceStatus.FUNDED, "Invoice not funded");
        
        invoices[tokenId].status = InvoiceStatus.DEFAULTED;

        emit InvoiceDefaulted(tokenId);
        emit InvoiceStatusChanged(tokenId, InvoiceStatus.DEFAULTED);
    }

    /**
     * @dev Cancel an invoice
     * @param tokenId The invoice NFT ID
     */
    function cancelInvoice(uint256 tokenId) external {
        require(_exists(tokenId), "Invoice does not exist");
        require(
            msg.sender == invoices[tokenId].borrower || hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "Only borrower or admin can cancel"
        );
        require(
            invoices[tokenId].status == InvoiceStatus.PENDING || 
            invoices[tokenId].status == InvoiceStatus.VALIDATED,
            "Cannot cancel funded invoice"
        );
        
        invoices[tokenId].status = InvoiceStatus.CANCELLED;

        emit InvoiceCancelled(tokenId);
        emit InvoiceStatusChanged(tokenId, InvoiceStatus.CANCELLED);
    }

    /**
     * @dev Get invoice details
     * @param tokenId The invoice NFT ID
     * @return Invoice struct
     */
    function getInvoice(uint256 tokenId) external view returns (Invoice memory) {
        require(_exists(tokenId), "Invoice does not exist");
        return invoices[tokenId];
    }

    /**
     * @dev Get total number of invoices minted
     */
    function totalSupply() external view returns (uint256) {
        return _tokenIdCounter.current();
    }

    /**
     * @dev Override required by Solidity for multiple inheritance
     */
    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }

    /**
     * @dev Override required by Solidity for multiple inheritance
     */
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    /**
     * @dev Override to support interfaces
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/RiskEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title RiskEngine
 * @dev On-chain risk validation and tier assignment for TILV platform
 * Integrates with off-chain AI risk scoring oracle
 */
contract RiskEngine is Ownable {
    
    struct RiskAssessment {
        uint256 score;              // Risk score 0-100 (0 = lowest risk)
        uint256 tier;               // 0 = Prime, 1 = Growth, 2 = Emerging
        uint256 timestamp;          // When assessment was made
        address validator;          // Who validated
        bool isValid;              // Whether assessment is still valid
    }

    // Oracle addresses authorized to submit risk scores
    mapping(address => bool) public authorizedOracles;
    
    // Invoice risk assessments: invoiceId => RiskAssessment
    mapping(uint256 => RiskAssessment) public assessments;
    
    // Risk tier thresholds
    uint256 public constant PRIME_MAX_SCORE = 30;
    uint256 public constant GROWTH_MAX_SCORE = 60;
    uint256 public constant EMERGING_MAX_SCORE = 100;

    // Assessment validity period (30 days)
    uint256 public assessmentValidityPeriod = 30 days;

    // Events
    event OracleAuthorized(address indexed oracle);
    event OracleRevoked(address indexed oracle);
    event RiskAssessed(
        uint256 indexed invoiceId,
        uint256 score,
        uint256 tier,
        address indexed validator
    );
    event AssessmentInvalidated(uint256 indexed invoiceId);

    constructor() {
        // Owner is automatically an authorized oracle
        authorizedOracles[msg.sender] = true;
        emit OracleAuthorized(msg.sender);
    }

    /**
     * @dev Submit risk assessment for an invoice
     * @param invoiceId The invoice NFT ID
     * @param score Risk score from AI engine (0-100)
     */
    function submitRiskAssessment(uint256 invoiceId, uint256 score) 
        external 
        onlyAuthorizedOracle 
    {
        require(score <= 100, "Score must be <= 100");
        
        uint256 tier = getTierForScore(score);

        assessments[invoiceId] = RiskAssessment({
            score: score,
            tier: tier,
            timestamp: block.timestamp,
            validator: msg.sender,
            isValid: true
        });

        emit RiskAssessed(invoiceId, score, tier, msg.sender);
    }

    /**
     * @dev Get tier based on risk score
     * @param score The risk score (0-100)
     * @return tier 0 = Prime, 1 = Growth, 2 = Emerging
     */
    function getTierForScore(uint256 score) public pure returns (uint256) {
        if (score <= PRIME_MAX_SCORE) {
            return 0;  // Prime
        } else if (score <= GROWTH_MAX_SCORE) {
            return 1;  // Growth
        } else {
            return 2;  // Emerging
        }
    }

    /**
     * @dev Check if risk assessment is still valid
     * @param invoiceId The invoice NFT ID
     * @return bool Whether assessment is valid
     */
    function isAssessmentValid(uint256 invoiceId) public view returns (bool) {
        RiskAssessment memory assessment = assessments[invoiceId];
        
        if (!assessment.isValid) {
            return false;
        }

        // Check if assessment has expired
        if (block.timestamp > assessment.timestamp + assessmentValidityPeriod) {
            return false;
        }

        return true;
    }

    /**
     * @dev Get risk assessment for an invoice
     * @param invoiceId The invoice NFT ID
     * @return RiskAssessment struct
     */
    function getRiskAssessment(uint256 invoiceId) 
        external 
        view 
        returns (RiskAssessment memory) 
    {
        return assessments[invoiceId];
    }

    /**
     * @dev Invalidate a risk assessment
     * @param invoiceId The invoice NFT ID
     */
    function invalidateAssessment(uint256 invoiceId) external onlyAuthorizedOracle {
        assessments[invoiceId].isValid = false;
        emit AssessmentInvalidated(invoiceId);
    }

    /**
     * @dev Add an authorized oracle
     * @param oracle Address to authorize
     */
    function authorizeOracle(address oracle) external onlyOwner {
        require(oracle != address(0), "Invalid address");
        require(!authorizedOracles[oracle], "Already authorized");
        
        authorizedOracles[oracle] = true;
        emit OracleAuthorized(oracle);
    }

    /**
     * @dev Revoke oracle authorization
     * @param oracle Address to revoke
     */
    function revokeOracle(address oracle) external onlyOwner {
        require(authorizedOracles[oracle], "Not authorized");
        
        authorizedOracles[oracle] = false;
        emit OracleRevoked(oracle);
    }

    /**
     * @dev Update assessment validity period
     * @param newPeriod New validity period in seconds
     */
    function setAssessmentValidityPeriod(uint256 newPeriod) external onlyOwner {
        require(newPeriod > 0, "Period must be > 0");
        assessmentValidityPeriod = newPeriod;
    }

    /**
     * @dev Modifier to check if caller is authorized oracle
     */
    modifier onlyAuthorizedOracle() {
        require(authorizedOracles[msg.sender], "Not an authorized oracle");
        _;
    }
}

contracts/VaultManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./InvoiceNFT.sol";

/**
 * @title VaultManager
 * @dev Manages liquidity vaults for invoice financing on TILV platform
 * Three risk tiers: Prime (low risk), Growth (mid risk), Emerging (high yield)
 */
contract VaultManager is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    enum VaultTier {
        PRIME,      // Low risk: 4-6% APY, risk score 0-30
        GROWTH,     // Medium risk: 8-12% APY, risk score 31-60
        EMERGING    // High yield: 15-25% APY, risk score 61-100
    }

    struct Vault {
        VaultTier tier;
        uint256 totalDeposits;          // Total USDT/USDC deposited
        uint256 totalAllocated;         // Amount allocated to invoices
        uint256 totalReturns;           // Total returns collected
        uint256 minDeposit;             // Minimum deposit amount
        uint256 maxRiskScore;           // Maximum risk score for invoices
        uint256 advanceRate;            // Percentage to advance (e.g., 80% = 8000)
        bool isActive;
    }

    struct InvestorPosition {
        uint256 depositedAmount;
        uint256 shares;                 // Share of vault pool
        uint256 depositTimestamp;
        uint256 claimedReturns;
    }

    // State variables
    IERC20 public stablecoin;          // USDT or USDC
    InvoiceNFT public invoiceNFT;
    
    // Vaults by tier
    mapping(VaultTier => Vault) public vaults;
    
    // Investor positions: tier => investor => position
    mapping(VaultTier => mapping(address => InvestorPosition)) public positions;
    
    // Invoice allocations: invoiceId => vault tier
    mapping(uint256 => VaultTier) public invoiceAllocations;
    
    // Invoice funding amounts
    mapping(uint256 => uint256) public invoiceFunding;

    // Constants
    uint256 public constant BASIS_POINTS = 10000;  // 100% = 10000
    uint256 public constant PLATFORM_FEE = 200;    // 2% platform fee

    // Events
    event VaultDeposit(address indexed investor, VaultTier tier, uint256 amount, uint256 shares);
    event VaultWithdrawal(address indexed investor, VaultTier tier, uint256 amount, uint256 shares);
    event InvoiceFunded(uint256 indexed invoiceId, VaultTier tier, uint256 amount);
    event InvoiceRepaid(uint256 indexed invoiceId, uint256 amount, uint256 yield);
    event YieldDistributed(VaultTier tier, uint256 totalYield);

    constructor(address _stablecoin, address _invoiceNFT) {
        require(_stablecoin != address(0), "Invalid stablecoin address");
        require(_invoiceNFT != address(0), "Invalid invoiceNFT address");
        
        stablecoin = IERC20(_stablecoin);
        invoiceNFT = InvoiceNFT(_invoiceNFT);

        // Initialize Prime Vault
        vaults[VaultTier.PRIME] = Vault({
            tier: VaultTier.PRIME,
            totalDeposits: 0,
            totalAllocated: 0,
            totalReturns: 0,
            minDeposit: 1000 * 10**6,      // 1000 USDT (assuming 6 decimals)
            maxRiskScore: 30,
            advanceRate: 8000,              // 80%
            isActive: true
        });

        // Initialize Growth Vault
        vaults[VaultTier.GROWTH] = Vault({
            tier: VaultTier.GROWTH,
            totalDeposits: 0,
            totalAllocated: 0,
            totalReturns: 0,
            minDeposit: 500 * 10**6,       // 500 USDT
            maxRiskScore: 60,
            advanceRate: 7500,              // 75%
            isActive: true
        });

        // Initialize Emerging Vault
        vaults[VaultTier.EMERGING] = Vault({
            tier: VaultTier.EMERGING,
            totalDeposits: 0,
            totalAllocated: 0,
            totalReturns: 0,
            minDeposit: 100 * 10**6,       // 100 USDT
            maxRiskScore: 100,
            advanceRate: 7000,              // 70%
            isActive: true
        });
    }

    /**
     * @dev Investor deposits stablecoin into a specific vault tier
     * @param tier The vault tier to deposit into
     * @param amount Amount of stablecoin to deposit
     */
    function deposit(VaultTier tier, uint256 amount) external nonReentrant {
        Vault storage vault = vaults[tier];
        require(vault.isActive, "Vault is not active");
        require(amount >= vault.minDeposit, "Amount below minimum deposit");

        InvestorPosition storage position = positions[tier][msg.sender];

        // Transfer stablecoin from investor
        stablecoin.safeTransferFrom(msg.sender, address(this), amount);

        // Calculate shares (proportional to deposit)
        uint256 shares;
        if (vault.totalDeposits == 0) {
            shares = amount;
        } else {
            shares = (amount * getTotalShares(tier)) / vault.totalDeposits;
        }

        // Update position
        position.depositedAmount += amount;
        position.shares += shares;
        if (position.depositTimestamp == 0) {
            position.depositTimestamp = block.timestamp;
        }

        // Update vault
        vault.totalDeposits += amount;

        emit VaultDeposit(msg.sender, tier, amount, shares);
    }

    /**
     * @dev Investor withdraws their funds and accrued yield
     * @param tier The vault tier to withdraw from
     * @param shares Number of shares to withdraw
     */
    function withdraw(VaultTier tier, uint256 shares) external nonReentrant {
        Vault storage vault = vaults[tier];
        InvestorPosition storage position = positions[tier][msg.sender];
        
        require(position.shares >= shares, "Insufficient shares");
        require(vault.totalDeposits >= vault.totalAllocated, "Insufficient liquidity");

        // Calculate withdrawal amount (principal + yield)
        uint256 totalValue = vault.totalDeposits + vault.totalReturns - vault.totalAllocated;
        uint256 totalShares = getTotalShares(tier);
        uint256 withdrawAmount = (shares * totalValue) / totalShares;

        // Update position
        position.shares -= shares;
        position.depositedAmount = (position.depositedAmount * (position.shares)) / (position.shares + shares);

        // Update vault
        vault.totalDeposits -= withdrawAmount;

        // Transfer stablecoin to investor
        stablecoin.safeTransfer(msg.sender, withdrawAmount);

        emit VaultWithdrawal(msg.sender, tier, withdrawAmount, shares);
    }

    /**
     * @dev Fund an invoice from appropriate vault based on risk score
     * @param invoiceId The invoice NFT ID
     */
    function fundInvoice(uint256 invoiceId) external onlyOwner nonReentrant {
        InvoiceNFT.Invoice memory invoice = invoiceNFT.getInvoice(invoiceId);
        
        require(
            invoice.status == InvoiceNFT.InvoiceStatus.VALIDATED,
            "Invoice must be validated"
        );

        // Determine vault tier based on risk score
        VaultTier tier = getVaultTierForRisk(invoice.riskScore);
        Vault storage vault = vaults[tier];

        require(vault.isActive, "Vault is not active");
        require(invoice.riskScore <= vault.maxRiskScore, "Risk score too high for vault");

        // Calculate funding amount
        uint256 fundingAmount = (invoice.amount * vault.advanceRate) / BASIS_POINTS;
        
        require(
            vault.totalDeposits - vault.totalAllocated >= fundingAmount,
            "Insufficient vault liquidity"
        );

        // Update vault allocation
        vault.totalAllocated += fundingAmount;
        invoiceAllocations[invoiceId] = tier;
        invoiceFunding[invoiceId] = fundingAmount;

        // Transfer funds to borrower
        stablecoin.safeTransfer(invoice.borrower, fundingAmount);

        // Update invoice status in NFT contract
        invoiceNFT.markAsFunded(invoiceId, fundingAmount);

        emit InvoiceFunded(invoiceId, tier, fundingAmount);
    }

    /**
     * @dev Process invoice repayment from buyer
     * @param invoiceId The invoice NFT ID
     * @param repaymentAmount Amount paid by buyer
     */
    function processRepayment(uint256 invoiceId, uint256 repaymentAmount) 
        external 
        onlyOwner 
        nonReentrant 
    {
        InvoiceNFT.Invoice memory invoice = invoiceNFT.getInvoice(invoiceId);
        require(
            invoice.status == InvoiceNFT.InvoiceStatus.FUNDED,
            "Invoice not in funded status"
        );

        VaultTier tier = invoiceAllocations[invoiceId];
        Vault storage vault = vaults[tier];
        uint256 fundedAmount = invoiceFunding[invoiceId];

        // Transfer repayment to contract
        stablecoin.safeTransferFrom(msg.sender, address(this), repaymentAmount);

        // Calculate platform fee
        uint256 platformFee = (repaymentAmount * PLATFORM_FEE) / BASIS_POINTS;
        uint256 vaultReturn = repaymentAmount - platformFee;

        // Calculate yield
        uint256 yield = vaultReturn > fundedAmount ? vaultReturn - fundedAmount : 0;

        // Update vault
        vault.totalAllocated -= fundedAmount;
        vault.totalReturns += yield;
        vault.totalDeposits += yield;  // Add yield to available liquidity

        // Mark invoice as paid
        invoiceNFT.markAsPaid(invoiceId, repaymentAmount);

        // Transfer platform fee to owner
        if (platformFee > 0) {
            stablecoin.safeTransfer(owner(), platformFee);
        }

        emit InvoiceRepaid(invoiceId, repaymentAmount, yield);
        emit YieldDistributed(tier, yield);
    }

    /**
     * @dev Get vault tier based on risk score
     * @param riskScore The risk score (0-100)
     * @return VaultTier appropriate for the risk
     */
    function getVaultTierForRisk(uint256 riskScore) public pure returns (VaultTier) {
        if (riskScore <= 30) {
            return VaultTier.PRIME;
        } else if (riskScore <= 60) {
            return VaultTier.GROWTH;
        } else {
            return VaultTier.EMERGING;
        }
    }

    /**
     * @dev Get total shares in a vault tier
     * @param tier The vault tier
     * @return Total shares
     */
    function getTotalShares(VaultTier tier) public view returns (uint256) {
        // In a production system, this would track all investors
        // For simplicity, we use total deposits as proxy
        return vaults[tier].totalDeposits;
    }

    /**
     * @dev Get investor position details
     * @param tier Vault tier
     * @param investor Investor address
     * @return Position details
     */
    function getPosition(VaultTier tier, address investor) 
        external 
        view 
        returns (InvestorPosition memory) 
    {
        return positions[tier][investor];
    }

    /**
     * @dev Get available liquidity in a vault
     * @param tier Vault tier
     * @return Available amount
     */
    function getAvailableLiquidity(VaultTier tier) external view returns (uint256) {
        Vault memory vault = vaults[tier];
        return vault.totalDeposits - vault.totalAllocated;
    }

    /**
     * @dev Get vault statistics
     * @param tier Vault tier
     * @return Vault struct
     */
    function getVault(VaultTier tier) external view returns (Vault memory) {
        return vaults[tier];
    }

    /**
     * @dev Admin function to update vault parameters
     * @param tier Vault tier
     * @param minDeposit New minimum deposit
     * @param maxRiskScore New maximum risk score
     * @param advanceRate New advance rate
     */
    function updateVaultParameters(
        VaultTier tier,
        uint256 minDeposit,
        uint256 maxRiskScore,
        uint256 advanceRate
    ) external onlyOwner {
        require(maxRiskScore <= 100, "Risk score must be <= 100");
        require(advanceRate <= BASIS_POINTS, "Advance rate must be <= 100%");

        Vault storage vault = vaults[tier];
        vault.minDeposit = minDeposit;
        vault.maxRiskScore = maxRiskScore;
        vault.advanceRate = advanceRate;
    }

    /**
     * @dev Admin function to activate/deactivate vault
     * @param tier Vault tier
     * @param active New active status
     */
    function setVaultActive(VaultTier tier, bool active) external onlyOwner {
        vaults[tier].isActive = active;
    }
}

